UPDATE policy_applications
customer_id = #{customerId}, product_type = #{productType}, product_name = #{productName}, coverage_amount = #{coverageAmount}, premium = #{premium}, payment_frequency = #{paymentFrequency}, insurance_period = #{insurancePeriod}, waiting_period = #{waitingPeriod}, beneficiary_relationship = #{beneficiaryRelationship}, application_date = #{applicationDate}, status = #{status}, created_by = #{createdBy}, updated_at = #{updatedAt},
WHERE application_id = #{applicationId}

mapper.select:
SELECT 
FROM policy_applications


        AND customer_id = #{q.customerId}
        AND product_type = #{q.productType}
        AND product_name = #{q.productName}
        AND payment_frequency = #{q.paymentFrequency}
        AND status = #{q.status}
        AND created_by = #{q.createdBy}

    AND application_date >= #{dateFrom}
    AND application_date <= #{dateTo}

ORDER BY application_date DESC NULLS LAST, application_id
